const debugMenu = document.createElement("div")
debugMenu.setAttribute("id", "debugMenu");
debugMenu.style.cssText = "position: fixed;z-index: 100;top:0px;color: white;height: 100vh;width: 100vw;pointer-events: none;"
document.body.appendChild(debugMenu);


//JUst Vatribles 👍//
let debugMenuShow = false;
let keyPress = "";
let controlKeys = []
let AllotControlanimationId = null;
let EngineLoopList = [];
let DisplayedWarn = false;
let AllotDeveloperTools = true;


// Function Area //
function IncializeGame() {
    debugMenuShow = false;
    DebugMenu.Show();
    keyPress = "";
    EngineLoopList = []


}

function DiffOf(a, b) {
    return Math.max(a, b) - Math.min(a, b)
}


function SetEngineLoop(func) {
    EngineLoopList.push(func);
}

function EngineLoop() {
    EngineLoopList.forEach(func => {
        func()
    })
    requestAnimationFrame(EngineLoop)
}

function RetainControl() {
    if (AllotControlanimationId !== null) {
        cancelAnimationFrame(AllotControlanimationId);
        AllotControlanimationId = null;
    }
}


// Key Detection
addEventListener("keypress", (e) => {
    keyPress = e.key
    if(e.key)
    switch (e.key) {
        case "`":
            debugMenuShow = !debugMenuShow;
            DebugMenu.Show();
            break;
        case "Control":
            document.querySelectorAll(".DebugInicator").forEach((e) => {
                if (e.classList.contains("VisablityElement")) return;
                e.style.opacity = 0;
            })
            break;
        case "Insert":
            document.querySelectorAll(".tileDataIndicator").forEach((Ele) => {
                Ele.style.opacity = 0;
            })
            document.querySelectorAll(".DebugEle").forEach((Ele) => {
                Ele.style.opacity = 0;
            })
            document.querySelectorAll(".collisionBox").forEach((box) => {
                box.style.opacity = 0;
            })
            document.querySelectorAll(".StageLable").forEach((ele) => {
                ele.style.opacity = 0;
            })
            document.querySelectorAll(".Point").forEach((e) => { e.style.backgroundColor = "black" })
            break;
    }

});
document.addEventListener("keyup",()=>{keyPress = ""})
window.addEventListener("keydown", (e) => {
    if (!controlKeys.includes(e.key)) {
        controlKeys.push(e.key);
    }
});

window.addEventListener("keyup", (e) => {
    const index = controlKeys.indexOf(e.key);
    if (index !== -1) {
        controlKeys.splice(index, 1);
    }
    switch (e.key) {
        case "Control":
            document.querySelectorAll(".DebugInicator").forEach((e) => {
                e.style.opacity = 1;
            })
            break;
        case "Insert":
            if (debugMenuShow) {
                document.querySelectorAll(".tileDataIndicator").forEach((Ele) => {
                    Ele.style.opacity = 1;
                })
                document.querySelectorAll(".DebugEle").forEach((Ele) => {
                    Ele.style.opacity = Ele.dataset.opacval;
                })
                document.querySelectorAll(".collisionBox").forEach((box) => {
                    box.style.opacity = 0.4;
                })
                document.querySelectorAll(".StageLable").forEach((ele) => {
                    ele.style.opacity = 1
                })
                document.querySelectorAll(".Point").forEach((e) => {
                    e.style.backgroundColor = "red"
                })
            }
            break;
    }
});
